const lead = $('3. Loop Leads Sequentially').item.json;
const aiMsg = $input.first().json.message?.content || $input.first().json;

let parsedText;
try {
  const obj = typeof aiMsg === 'string' ? JSON.parse(aiMsg) : aiMsg;
  parsedText = obj.wa_message || obj.message || aiMsg;
} catch (e) {
  parsedText = `Halo tim ${lead.clean_name || lead.name}, salam kenal saya Fahru dari Juragan by Anak Bawang (produsen Bawang Goreng Asli Boyolali, Halal ID33110018517710724). Boleh kami kirimkan 1 box sampel tester (Grade S Murni & Grade A) langsung ke dapur ${lead.clean_name || lead.name} di Singapore? Terima kasih banyak 🙏`;
}

// Format phone (remove spaces, symbols)
const cleanPhone = (lead.phone || '').replace(/[^0-9]/g, '');

return [{
  json: {
    lead_id: lead.lead_id,
    restaurant_name: lead.clean_name,
    phone: cleanPhone,
    message: parsedText
  }
}];
